package com.shengyu.framework.netty.core;import cn.hutool.core.util.IdUtil;import com.shengyu.framework.common.enums.im.ImChatSceneEnum;import com.shengyu.framework.common.enums.im.ImConstants;import lombok.*;import java.util.Date;/** * 通信数据格式 * * @author zhusy * @since 2022/11/13 */@Data@AllArgsConstructor@NoArgsConstructor@Builder@ToStringpublic class ImChat {    /**     * 通信数据ID     */    @Builder.Default    private Long id = IdUtil.getSnowflakeNextId();    /**     * 数据类型     * {@link ImChatSceneEnum}     */    private String type;    /**     * 发送状态,业务方自己定义设置规则     * {@link ImConstants.ChatSendEnum}     */    private Integer sendStatus;    @Builder.Default    private String msg = "";    /**     * code码值     */    @Builder.Default    private String code = "";    /**     * 发送者ID     */    private String fromId;    /**     * 接收者ID     */    private String toId;    /**     * 数据组装创建时间     */    @Builder.Default    private Date createTime = new Date();    /**     * 需要发送的json数据     */    @Builder.Default    private Object data = null;}